import { Controller, Get, Res, HttpStatus } from '@nestjs/common';

@Controller('users')
export class UsersController {
  @Get()
  async findAll(@Res() res: any) {
    try {
      const users = await this.service.getUsers();
      return res.json(users);
    } catch (err: any) {
      return res.status(HttpStatus.INTERNAL_SERVER_ERROR).json({
        error: err.message,
        stack: err.stack // ❌ Dangerous security leak!
      });
    }
  }
}

import { ExceptionFilter, Catch, ArgumentsHost, HttpException, HttpStatus, Logger } from '@nestjs/common';
import { Request, Response } from 'express';

@Catch() // Catches ALL unhandled exceptions (HttpException and raw Error)
export class AllExceptionsFilter implements ExceptionFilter {
  private readonly logger = new Logger(AllExceptionsFilter.name);

  catch(exception: unknown, host: ArgumentsHost) {
    const ctx = host.switchToHttp();
    const response = ctx.getResponse<Response>();
    const request = ctx.getRequest<Request>();

    const status =
      exception instanceof HttpException
        ? exception.getStatus()
        : HttpStatus.INTERNAL_SERVER_ERROR;

    const message =
      exception instanceof HttpException
        ? exception.getResponse()
        : 'Internal server error';

    this.logger.error(`HTTP ${status} Error on ${request.url}`, exception instanceof Error ? exception.stack : '');

    // ✅ Sanitized, standardized enterprise error envelope:
    response.status(status).json({
      statusCode: status,
      timestamp: new Date().toISOString(),
      path: request.url,
      error: typeof message === 'object' ? message : { message }
    });
  }
}
